<!DOCTYPE html>
<html dir="rtl">
<head>
    <meta charset="UTF-8" />
    <title>{{$data->service->name}}</title>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
        href="https://fonts.googleapis.com/css2?family=Cairo:wght@200..1000&display=swap"
        rel="stylesheet"
    />
    <style>
        html,
        body {
            margin: 0;
            height: 95%;
            font-family: "Cairo", sans-serif;
        }
        body {
        h1,
        h2,
        h3,
        h4,
        h5,
        h6,
        p {
            margin: 0;
            padding: 0;
        }
        padding: 0 2rem;
        position: relative;
        }

        .header-container {
            margin-top: 3rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
        .header-content {
            display: flex;
            /* gap: 1rem; */
            flex-direction: column;
            text-align: end;
        }
        .header-tax-number {
            font-size: 14px;
        }
        .content-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-direction: row;
        }
        .content-header-client {
            align-self: flex-start;
        h4 {
            color: #bac6e0;
        }
        }
        .content-header-details {
            display: flex;
            flex-direction: column;
            gap: 0.25rem;
        }
        .detail-item {
            text-align: center;
            font-size: 12px;
        }
        .details-total-amount {
            display: flex;
            flex-direction: row;
            gap: 4px;
            width: 200px;
            font-size: 12px;
        }
        .details-total {
            height: 1.5rem;
            background-color: #dbd8d8;
            flex: 1;
            padding: 4px 0;
        p {
            padding: 0;
            margin: 0;
        }
        }
        .details-total-bold {
            font-weight: bold;
        }
        .details-total-amount > .details-total:nth-of-type(1) {
            text-align: end;
        }
        .details-total-amount > .details-total:nth-of-type(2) {
            text-align: start;
        }
        .table-container {
            display: flex;
            flex-direction: column;
            margin-top: 1rem;
        }
        .grid-container {
            display: grid;
            grid-template-columns: 0.15fr 4fr repeat(7, 1fr);
            grid-column-gap: 0.75rem;
            grid-row-gap: 0px;
        }
        .table-header-container {
            display: flex;
            flex-direction: column;
            font-weight: bolder;
            font-size: 14px;
        p {
            width: 52px;
            display: inline-block;
            font-size: 12px;
            font-weight: bolder;
        }
        }
        .table-cell-font {
            font-weight: 400;
            font-size: 14px;
        }
        .table-cell--product {
            display: flex;
            flex-direction: column;
            font-weight: bolder;
            font-size: 14px;
        }
        .summary-container {
            display: flex;
        }
        .summary-content-container {
            width: 60%;
            text-align: end;
            margin-right: auto;
            display: flex;
            gap: 0.5rem;
            flex-direction: column;
        }
        .summary-item {
            display: flex;
            flex-direction: row;
            justify-content: space-between;
            font-weight: bolder;
            font-size: 14px;
        }
        .description-container {
            margin-top: 1rem;
        h6 {
            color: #bac6e0;
        }
        }
        .footer-content {
            position: absolute;
            bottom: 0;
            text-align: center;
            width: 95%;
        }
    </style>
</head>
<body>
<!-- Header with text and logo -->
<header>
    <div class="header-container">
        <img
            width="120px"
            height="80px"
            src="data:image/jpeg;base64,"
        />
        <div class="header-content">
            <div class="header-main-content">
                <!-- @val: header-tax-type-arabic -->
                <h3>فاتورة ضريبية مبسطة</h3>
                <!-- @val: header-tax-type-english -->
                <h5>Simplified Tax Invoice</h5>
                <!-- @val: header-office -->
                <h5>
                    مكتب المحامي رامي الحامد للمحاماة و الاستشارات الشرعية و القانونية
                </h5>
                <!-- @val: header-office-address -->
                <p></p>
            </div>
            <div class="header-tax-number">
                <!-- @val: tax-number -->
                <p><strong>الرقم الضريبي : </strong>31045265821224</p>
            </div>
        </div>
    </div>
    <hr />
</header>
<!-- content -->
<section>
    <div class="content-header">
        <div class="content-header-client">
            <h4>تفاصيل بيانات العميل</h4>
            <!-- @val: client-type -->
            <h5>{{$data->service->client->name}}</h5>
        </div>
        <div class="content-header-details">
            <!-- @val: reference-number -->
            <span class="detail-item"><strong>المرجع:</strong> IN4 168</span>
            <!-- @val: invoice-type -->
            <span class="detail-item"
            ><strong>نوع الفاتورة: </strong>فاتورة ضريبية مبسطة</span
            >
            <!-- @val: created-at -->
            <span class="detail-item"
            ><strong>تاريخ الإصدار: </strong>{{$data->created_at}}</span
            >
            <!-- @val: pay-date -->
            <span class="detail-item"
            ><strong>تاريخ الاستحقاق: </strong>{{$data->date}}</span
            >
            <div class="details-total-amount">
            <span class="details-total details-total-bold"
            >المبلغ المستحق:
            </span>
                <!-- @val: total-amount -->
                <span class="details-total">{{$data->total_amount}} رس</span>
            </div>
        </div>
    </div>
    <!-- table -->
    <div class="table-container">
        <!-- table header -->
        <div class="grid-container">
            <div class="table-header-container">#</div>
            <div class="table-header-container">
                <p>{{$data->service->name}}</p>
                <p>Products</p>
            </div>
            <div class="table-header-container">
                <p>الكمية</p>
                <p>Qty</p>
            </div>
            <div class="table-header-container">
                <p>سعر الوحدة</p>
                <p>Unit Price</p>
            </div>
            <div class="table-header-container">
                <p>الخصم</p>
                <p>Discount</p>
            </div>
            <div class="table-header-container">
                <p>الاجمالي قبل الضريبة</p>
                <p>Total Before VAT</p>
            </div>
            <div class="table-header-container">
                <p>الضريبة</p>
                <p>%</p>
                <p>VAT %</p>
            </div>
            <div class="table-header-container">
                <p>الضريبة</p>
                <p>VAT</p>
            </div>
            <div class="table-header-container">
                <p>الإجمالي</p>
                <p>Amount</p>
            </div>
        </div>
        <!-- table content -->
        <!-- repeat this in your loop on items and repeat this block for every entity in list -->
        <div class="grid-container">
            <!-- @val: table row index -->
            <div class="table-header-container">1</div>
            <div class="table-cell--product">
                <!-- @val: product-name -->
                <p>
                    استشارة قانونية - استشارة قانونية<br />
                    2
                </p>
                <!-- @val: product-description -->
                <p class="table-cell-font">استشارة قانونية للاستاذة بسمة هدنان</p>
            </div>
            <div class="table-header-container table-cell-font">
                <!-- @val: quantity -->
                <p>1.0 وحدة</p>
            </div>
            <div class="table-header-container table-cell-font">
                <!-- @val: unit-price -->
                <p>217.3913</p>
                <!-- @val: currency -->
                <p>ر.س</p>
            </div>
            <div class="table-header-container table-cell-font">
                <!-- @val: discount -->
                <p>0.0%</p>
                <p>0.00 ر.س</p>
            </div>
            <div class="table-header-container table-cell-font">
                <!-- @val: total-before-vat -->
                <p>{{$data->amount}}</p>
                <p>ر.س</p>
            </div>
            <div class="table-header-container table-cell-font">
                <!-- @val: vat-percentage -->
                <p>{{$data->service->tax}}</p>
            </div>
            <div class="table-header-container table-cell-font">
                <!-- @val: vat-value -->
                <p>{{$data->tax_amount}}ر.س</p>
                <p>ر.س</p>
            </div>
            <div class="table-header-container table-cell-font">
                <p>250.00</p>
                <p>ر.س</p>
            </div>
        </div>
        <!-- summary -->
        <div class="summary-container">
            <div class="summary-content-container">
                <div class="summary-item">
                    <!-- @val: total-before-tax -->
                    <div>الاجمالي قبل الضريبة:</div>
                    <div>{{$data->amount}}ر.س</div>
                </div>
                <div class="summary-item">
                    <!-- @val: total-tax -->
                    <div>اجمالي الضريبة:</div>
                    <div>{{$data->tax_amount}} ر.س</div>
                </div>
                <div class="summary-item">
                    <!-- @val: total -->
                    <div>المجموع:</div>
                    <div>{{$data->total_amount}} ر.س</div>
                </div>
                <div class="summary-item">
                    <!-- @val: payed-by -->
                    <div>دفعت بواسطة سند {{$data->paid_to}} في  {{$data->paid_at}}:</div>
                    <div>{{$data->total_amount}}  ر.س</div>
                </div>
                <div>
                    <hr style="width: 100%; margin-top: -4px" />
                    <div class="summary-item">
                        <!-- @val: due-amount -->
                        <div>المبلغ المستحق:</div>
                        <div>{{$data->total_amount}}  ر.س</div>
                    </div>
                    <hr style="width: 100%" />
                </div>
            </div>
        </div>
        <div class="description-container">
            <h6>الوصف</h6>
            <hr />
            <div class="description-content">
                <!-- @val:client-name -->
                <p style="font-size: 12px">{{$data->service->client->name}}</p>
                <img
                    src="https://via.placeholder.com/150"
                    alt="client-signature"
                    height="130"
                    width="130px"
                />
            </div>
        </div>
    </div>
</section>
</body>
</html>
